  "uo-uo-seiryu": { desc: "A Mythical Zoan fruit that lets the user transform into a giant azure dragon that flies through the sky, breathes fire, and creates clouds. The user switches between dragon and human forms, and in hybrid form fights with a club and Haki. Vegapunk created an artificial version of this fruit from Kaido's lineage factor.", holders: [{ note: "Defeated by Luffy in Wano Country. Whether he is alive is unknown" }] },
  "ryu-ryu-pteranodon-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into the flying reptile Pteranodon. It lets the user fly around at high speed, and combined with the Lunarian race's toughness and flames, it supports the strength of King of the All-Stars.", holders: [{}] },
  "ryu-ryu-brachiosaurus-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into Brachiosaurus, a huge plant-eating dinosaur with a long neck. Queen fights by combining it with the cyborg modifications to his own body.", holders: [{}] },
  "zou-zou-mammoth-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into a mammoth. Jack ravaged the country of Zou and crushed buildings whole with his massive body.", holders: [{}] },
  "neko-neko-sabertooth-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into a sabertooth tiger. Who's-Who, a former CP9 member, fights with Six Powers techniques and sharp fangs.", holders: [{}] },
  "ryu-ryu-pachycephalosaurus-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into Pachycephalosaurus, a hard-headed dinosaur. It made Ulti's signature headbutt even stronger.", holders: [{}] },
  "ryu-ryu-spinosaurus-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into Spinosaurus, a carnivorous dinosaur with a sail on its back. Page One stood in the Straw Hats' way in Wano Country.", holders: [{}] },
  "ryu-ryu-triceratops-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into a Triceratops. Sasaki of the Flying Six showed his own fighting style, such as spinning his frill to fly.", holders: [{}] },
  "kumo-kumo-rosamygale-fruit": { desc: "An Ancient Zoan fruit that lets the user transform into a giant spider from ancient times. The user can tangle prey in threads and also burn them with threads of fire. Black Maria of the Flying Six fought Robin.", holders: [{}] },
  "inu-inu-okuchi-fruit": { desc: "A Mythical Zoan fruit that lets the user transform into Okuchi no Makami, a wolf god. The user is wrapped in cold air and also has powers of protective barriers and healing. Kaido's child Yamato called themself Kozuki Oden and fought alongside Luffy and the others.", holders: [{ note: "The power's true nature was revealed in the battle of Onigashima" }] },
  "mori-mori-fruit": { desc: "A Logia fruit that lets the user turn their body into a forest (plants). The user puts down roots and absorbs nutrients from the earth, and can live a long time without eating. Ryokugyu even drew out people's life force through his roots.", holders: [{}] },
